function buildColormap(id, label, colors, { diverging = false } = {}) {
  const sampleInto = makeColormapSamplerInto(colors);
  return {
    id,
    label,
    diverging,
    colors,
    cssStops: colors.map(rgbToCss),
    sampleInto,
    sample: (t) => sampleInto(t, [0, 0, 0])
  };
}
